use std::env;

fn add(a: &str, b: &str) -> String {
    let a = a.as_bytes();
    let b = b.as_bytes();
    let mut result = Vec::new();
    let mut i = a.len();
    let mut j = b.len();
    let mut carry = 0;
    while i > 0 || j > 0 || carry != 0 {
        let mut sum = carry;
        if i > 0 {
            i -= 1;
            sum += (a[i] - b'0') as u32;
        }
        if j > 0 {
            j -= 1;
            sum += (b[j] - b'0') as u32;
        }
        result.push(b'0' + (sum % 10) as u8);
        carry = sum / 10;
    }
    result.reverse();
    String::from_utf8(result).unwrap()
}

fn main() {
    let mut args = env::args();
    args.next();
    let n: usize = args.next().unwrap().parse().unwrap();
    let mut a = String::from("1");
    let mut b = String::from("1");
    for _ in 0..n {
        let next = add(&a, &b);
        a = b;
        b = next;
    }
    println!("{}", a);
}
